#!/usr/bin/env node
/**
 * Tests for hooks/nudges.js, the single entry point for context-nudge and edit-nudge. Zero
 * dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * The nudges' own rules (bands, the third edit, subagents, scratch files) are covered by their test
 * files; here only the wiring: the right nudges per event, one merged output, and
 * silence on anything else. Each case gets its own CLAUDE_CONFIG_DIR.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const HOOK = join(dirname(fileURLToPath(import.meta.url)), '..', 'hooks', 'nudges.js');
const created = [];
// An edit is scratch when its file sits under the temp dir, where the sandboxes live: the child gets its own temp dir
// inside the sandbox, so `a.cs` at the sandbox root counts, and no repo (nor its deliver perimeter) is in the way.
const childEnv = (config) => {
  const tmp = join(config, 'tmp');
  return { ...process.env, CLAUDE_CONFIG_DIR: config, CLAUDE_NUDGE_STEPS: '120000,200000,320000', TEMP: tmp, TMP: tmp, TMPDIR: tmp };
};
process.on('exit', () => {
  for (const dir of created) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp */ } }
});

function sandbox() {
  const config = mkdtempSync(join(tmpdir(), 'nudges-'));
  created.push(config);
  mkdirSync(join(config, '.cache'));
  return config;
}

const snapshot = (config, id, used_tokens) => writeFileSync(
  join(config, '.cache', `context-${id}.json`),
  JSON.stringify({ used_tokens, window: 1_000_000, warm: true, at: Date.now() }),
);

/** The hook's `hookSpecificOutput` for one payload, null when it said nothing. */
function fire(config, payload) {
  const r = spawnSync(process.execPath, [HOOK], {
    input: typeof payload === 'string' ? payload : JSON.stringify(payload),
    encoding: 'utf8',
    cwd: config,                                // outside any repo: scope-guard must not read the real deliver perimeter
    env: childEnv(config),
  });
  assert.equal(r.status, 0, r.stderr);
  return r.stdout ? JSON.parse(r.stdout).hookSpecificOutput : null;
}

const prompt = (config, id = 'sess-1') => fire(config, { session_id: id, hook_event_name: 'UserPromptSubmit', prompt: 'x' });
const edit = (config) => fire(config, { session_id: 'sess-1', hook_event_name: 'PostToolUse', tool_name: 'Edit', tool_input: { file_path: 'a.cs' }, cwd: config });

test('UserPromptSubmit: the context nudge speaks once per band', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', 210_000);
  const out = prompt(config);
  assert.equal(out.hookEventName, 'UserPromptSubmit');
  assert.match(out.additionalContext, /^Context at 210k tokens/);
  assert.equal(prompt(config), null, 'same band: already said');
});

test('UserPromptSubmit: the edit counter is not touched (edit-nudge tells turns from history.jsonl)', () => {
  const config = sandbox();
  edit(config);
  edit(config);
  assert.equal(prompt(config), null);
  assert.ok(existsSync(join(config, '.cache', 'edits-sess-1.json')));
});

test('PostToolUse: the third edit nudges towards the implementer, never the context line', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', 330_000);
  assert.match(edit(config).additionalContext, /^Context ≥ 120k/, 'the large-context line, once per session');
  assert.equal(edit(config), null);
  const third = edit(config);
  assert.equal(third.hookEventName, 'PostToolUse');
  assert.match(third.additionalContext, /\bimplementer\b/);
  assert.doesNotMatch(third.additionalContext, /Context at/);
});

test('PostToolUse: the formatter runs in the same process as the nudges', () => {
  const config = sandbox();
  const project = mkdtempSync(join(tmpdir(), 'nudges-fmt-'));
  created.push(project);
  mkdirSync(join(project, 'node_modules', '.bin'), { recursive: true });
  for (const shim of ['prettier', 'prettier.cmd']) writeFileSync(join(project, 'node_modules', '.bin', shim), '');
  writeFileSync(join(project, 'package.json'), '{ "name": "web" }');
  writeFileSync(join(project, '.prettierrc'), '{}');
  writeFileSync(join(project, 'main.ts'), 'export {};');
  const payload = { session_id: 'sess-1', hook_event_name: 'PostToolUse', tool_name: 'Edit', tool_input: { file_path: join(project, 'main.ts') } };
  const r = spawnSync(process.execPath, [HOOK, '--dry-run'], {
    input: JSON.stringify(payload), encoding: 'utf8', cwd: config, env: { ...process.env, CLAUDE_CONFIG_DIR: config },
  });
  assert.equal(r.status, 0, r.stderr);
  assert.match(r.stdout, /^prettier --write .*main\.ts$/m, 'format-on-edit ran inside nudges.js');
});

test('settings.json: one PostToolUse node for the edits, with the formatter timeout', () => {
  const { hooks } = JSON.parse(readFileSync(join(dirname(HOOK), '..', 'settings.json'), 'utf8'));
  const group = hooks.PostToolUse.find((g) => g.matcher === 'Write|Edit|MultiEdit');
  assert.equal(group.hooks.length, 1);
  assert.ok(group.hooks[0].args.join(' ').includes('nudges.js'));
  assert.equal(group.hooks[0].timeout, 30);
  assert.ok(!JSON.stringify(hooks).includes('format-on-edit.js'), 'no separate formatter entry');
});

test('an unknown event, a bad payload or an empty one → silent, exit 0', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', 330_000);
  assert.equal(fire(config, { session_id: 'sess-1', hook_event_name: 'Stop' }), null);
  assert.equal(fire(config, 'not json'), null);
  assert.equal(fire(config, ''), null);
});

/** The pattern an older settings.json wires: `node -e "require(<hook>)"`, where `require.main` is undefined. */
function viaRequire(config, hook, payload) {
  const file = join(dirname(HOOK), hook);
  const r = spawnSync(process.execPath, ['-e', `try{require(${JSON.stringify(file)})}catch{process.exit(0)}`], {
    input: JSON.stringify(payload),
    encoding: 'utf8',
    cwd: config,
    env: childEnv(config),
  });
  assert.equal(r.status, 0, r.stderr);
  return r.stdout ? JSON.parse(r.stdout).hookSpecificOutput : null;
}

test('an older settings.json that requires a nudge directly still gets its output', () => {
  const config = sandbox();
  const edit = { session_id: 'sess-1', hook_event_name: 'PostToolUse', tool_name: 'Edit', tool_input: { file_path: 'a.cs' }, cwd: config };
  assert.equal(viaRequire(config, 'edit-nudge.js', edit), null);
  assert.equal(viaRequire(config, 'edit-nudge.js', edit), null);
  assert.match(viaRequire(config, 'edit-nudge.js', edit).additionalContext, /\bimplementer\b/);
  snapshot(config, 'sess-2', 210_000);
  const out = viaRequire(config, 'context-nudge.js', { session_id: 'sess-2', hook_event_name: 'UserPromptSubmit', prompt: 'x' });
  assert.match(out.additionalContext, /^Context at 210k tokens/);
});
